import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(a, b, c):
    # Assume a < b < c
    if gcd3(a, b, c) != 1:
        return False

    # Conditions derived from pairwise divisibility requirement for |U|=3:
    # c | ab
    if (a * b) % c != 0:
        return False

    # b | ac
    if (a * c) % b != 0:
        return False

    # a | bc
    if (b * c) % a != 0:
        return False

    return True

def find_good_numbers(max_product):
    good_numbers = []

    # Iterate over possible sets {a, b, c} such that a < b < c
    # We estimate max a, b, c based on max_product.
    # If max_product = 10000, then c <= 10000 / (2*3) ~ 1666.

    # Start search around the known range (up to 1764). Let's search up to a product of 10000 initially.

    limit_c = int(math.ceil(max_product / 6)) if max_product > 0 else 100

    print(f"Starting search up to product {max_product}. Estimated max c: {limit_c}")

    for a in range(2, limit_c // 6 + 1):
        for b in range(a + 1, limit_c // (a + 1) + 1):
            # Estimate upper bound for c
            max_c = max_product // (a * b)

            for c in range(b + 1, max_c + 1):
                if is_good_set(a, b, c):
                    m = a * b * c
                    # Check if we already found this product through a different set
                    # For simplicity and given the task, we will collect all unique products and sort them.
                    if m not in good_numbers:
                        good_numbers.append(m)

    return sorted(good_numbers)

# We need ranks 11 through 20. The 10th is 1764. Let's search up to a product of 15000 to be safe.
MAX_PRODUCT_SEARCH = 15000
all_good_numbers = find_good_numbers(MAX_PRODUCT_SEARCH)

# We need to ensure the list starts correctly and extract ranks 11-20
print("\\n--- All Found Good Numbers (Sorted) ---")
print(all_good_numbers[:25]) # Print first 25 to verify the start

# Filter out the first 10 known numbers to check subsequent ones
known_ranks = [36, 100, 144, 196, 324, 484, 576, 900, 1521, 1764]
current_ranks = []
for m in all_good_numbers:
    if m not in known_ranks:
        current_ranks.append(m)

print("\\n--- Ranks 11 through 20 ---")
if len(current_ranks) >= 10:
    ranks_11_to_20 = current_ranks[:10]
    print(ranks_11_to_20)
else:
    print(f"Could only find {len(current_ranks)} further good numbers.")

# Test the smallest candidate derived from the structure U={p1 p2, p1 p3, p2 p4, p3 p4}
# Primes: p1=2, p2=3, p3=5, p4=7
a = 2 * 3  # 6
b = 2 * 5  # 10
c = 3 * 7  # 21
d = 5 * 7  # 35
U = [a, b, c, d]

def check_condition_2(U):
    for i in range(4):
        for j in range(i + 1, 4):
            x = U[i]
            y = U[j]
            product = x * y

            found_divisor = False
            for k in range(4):
                if k != i and k != j:
                    z = U[k]
                    if product % z == 0:
                        found_divisor = True
                        break

            if not found_divisor:
                return False, (x, y)
    return True, None

is_good, failing_pair = check_condition_2(U)

print(f"Set U: {U}")
print(f"Condition 2 satisfied: {is_good}")
if not is_good:
    print(f"Failing pair (x, y): {failing_pair}")

